diff --git a/src/log.ts b/src/log.ts
index 4892c8b..080a1d5 100644
--- a/src/log.ts
+++ b/src/log.ts
@@ -1,3 +1,27 @@
+const queue: string[] = [];
+let scheduled = false;
+
+const flush = (): void => {
+  if (queue.length === 0) {
+    scheduled = false;
+    return;
+  }
+
+  const batch = queue.splice(0, queue.length);
+  process.stdout.write(batch.join(''));
+
+  if (queue.length > 0) {
+    setImmediate(flush);
+  } else {
+    scheduled = false;
+  }
+};
+
 export const log = (message: string): void => {
-  process.stdout.write(`${JSON.stringify({ message })}\n`);
+  queue.push(`${JSON.stringify({ message })}\n`);
+
+  if (!scheduled) {
+    scheduled = true;
+    setImmediate(flush);
+  }
 };
